SourceCode.Declaration:
/// <summary>
/// A business event endpoint of an environment. Its business events are activated in all companies
/// or in the companies selected for the endpoint.
/// </summary>
public class BDREndpoint extends common
{
}

Method.Source:
    /// <summary>
    /// Checks the fields Microsoft's endpoint tables require for the endpoint type.
    /// </summary>
    public boolean validateWrite()
    {
        boolean ret = super();

        if (!BDREndpoint::isSupportedType(this.EndpointType))
        {
            return checkFailed("@BDR:ErrEndpointType") && ret;
        }

        // A second endpoint with the same name is refused here, before the dialog sends Microsoft's test event.
        if (!this.RecId)
        {
            BDREndpoint other;

            select firstonly RecId from other
                where other.EnvironmentId == this.EnvironmentId
                    && other.EndpointName == this.EndpointName;

            if (other.RecId)
            {
                ret = checkFailed(strFmt("@BDR:MsgEndpointExists", this.EndpointName)) && ret;
            }
        }

        // BusinessEventsAzureEndpoint: application ID, client secret and Key Vault are mandatory.
        ret = this.checkRequired(fieldNum(BDREndpoint, AzureAppId)) && ret;
        ret = this.checkRequired(fieldNum(BDREndpoint, KeyVaultDnsName)) && ret;
        ret = this.checkRequired(fieldNum(BDREndpoint, KeyVaultSecretName)) && ret;
        ret = this.checkRequired(fieldNum(BDREndpoint, SecretName)) && ret;

        switch (this.EndpointType)
        {
            // Queue, topic, hub and container names are mandatory in their endpoint tables.
            case BusinessEventsEndpointType::AzureServiceBusQueue:
            case BusinessEventsEndpointType::AzureServiceBusTopic:
            case BusinessEventsEndpointType::AzureEventHub:
            case BusinessEventsEndpointType::AzureBlobStorage:
                ret = this.checkRequired(fieldNum(BDREndpoint, ResourceName)) && ret;
                break;

            case BusinessEventsEndpointType::AzureEventGrid:
                ret = this.checkRequired(fieldNum(BDREndpoint, EndpointUrl)) && ret;
                break;
        }

        return ret;
    }

    private boolean checkRequired(FieldId _fieldId)
    {
        if (this.(_fieldId))
        {
            return true;
        }

        return checkFailed(strFmt("@BDR:ErrEndpointFieldRequired", fieldId2PName(tableNum(BDREndpoint), _fieldId), this.EndpointType));
    }

    /// <summary>
    /// The endpoint types Microsoft's endpoint configuration form offers.
    /// </summary>
    public static boolean isSupportedType(BusinessEventsEndpointType _type)
    {
        switch (_type)
        {
            case BusinessEventsEndpointType::AzureServiceBusQueue:
            case BusinessEventsEndpointType::AzureServiceBusTopic:
            case BusinessEventsEndpointType::AzureEventGrid:
            case BusinessEventsEndpointType::AzureEventHub:
            case BusinessEventsEndpointType::AzureBlobStorage:
            case BusinessEventsEndpointType::Http:
                return true;
        }

        return false;
    }

    /// <summary>
    /// Builds Microsoft's endpoint record for this row, without saving it.
    /// </summary>
    /// <param name = "_appSecret">The client secret of the application; empty to leave it out.</param>
    /// <returns>The concrete endpoint record, for example <c>BusinessEventsServiceBusQueueEndpoint</c>.</returns>
    public BusinessEventsAzureEndpoint standardEndpoint(str _appSecret)
    {
        BusinessEventsAzureEndpoint azureEndpoint;
        BusinessEventsServiceBusQueueEndpoint queueEndpoint;
        BusinessEventsServiceBusTopicEndpoint topicEndpoint;
        BusinessEventsEventGridEndpoint eventGridEndpoint;
        BusinessEventsEventHubEndpoint eventHubEndpoint;
        BusinessEventsAzureBlobStorageEndpoint blobEndpoint;

        switch (this.EndpointType)
        {
            case BusinessEventsEndpointType::AzureServiceBusQueue:
                queueEndpoint.QueueName = this.ResourceName;
                queueEndpoint.QueueSKU = this.ServiceBusSku;
                azureEndpoint = queueEndpoint;
                break;

            case BusinessEventsEndpointType::AzureServiceBusTopic:
                topicEndpoint.TopicName = this.ResourceName;
                topicEndpoint.TopicSKU = this.ServiceBusSku;
                azureEndpoint = topicEndpoint;
                break;

            case BusinessEventsEndpointType::AzureEventGrid:
                eventGridEndpoint.EndpointURL = this.EndpointUrl;
                azureEndpoint = eventGridEndpoint;
                break;

            case BusinessEventsEndpointType::AzureEventHub:
                eventHubEndpoint.HubName = this.ResourceName;
                eventHubEndpoint.EventHubSKU = this.EventHubSku;
                azureEndpoint = eventHubEndpoint;
                break;

            case BusinessEventsEndpointType::AzureBlobStorage:
                blobEndpoint.ContainerName = this.ResourceName;
                azureEndpoint = blobEndpoint;
                break;

            case BusinessEventsEndpointType::Http:
                // HTTPS endpoint: the URL itself is stored in Azure Key Vault.
                break;

            default:
                throw error("@BDR:ErrEndpointType");
        }

        azureEndpoint.Name = this.EndpointName;
        azureEndpoint.Description = this.Description;
        azureEndpoint.Type = this.EndpointType;
        azureEndpoint.AzureAppId = this.AzureAppId;
        azureEndpoint.KeyVaultDnsName = this.KeyVaultDnsName;
        azureEndpoint.KeyVaultSecretName = this.KeyVaultSecretName;

        if (_appSecret)
        {
            azureEndpoint.editAzureAppSecret(true, _appSecret);
        }

        return azureEndpoint;
    }

    /// <summary>
    /// Validates the endpoint the way Microsoft's endpoint setup does: reads the Key Vault secret
    /// and sends a test event (<c>BusinessEventsEndpointManager::validateEndpoint</c>).
    /// </summary>
    /// <param name = "_appSecret">The client secret of the application, used for this test only.</param>
    /// <returns>True if the test event was sent.</returns>
    public boolean validateConnection(str _appSecret)
    {
        if (!_appSecret)
        {
            return checkFailed(strFmt("@BDR:ErrValidationSecretMissing", this.EndpointName));
        }

        if (!BusinessEventsEndpointManager::validateEndpoint(this.standardEndpoint(_appSecret)))
        {
            return false;
        }

        info(strFmt("@BDR:MsgEndpointValidated", this.EndpointName));

        return true;
    }

    /// <summary>
    /// Checks whether the row is new or a field that the connection depends on has changed.
    /// </summary>
    public boolean connectionChanged()
    {
        BDREndpoint saved = this.orig();

        return !this.RecId
            || this.EndpointType != saved.EndpointType
            || this.ResourceName != saved.ResourceName
            || this.EndpointUrl != saved.EndpointUrl
            || this.ServiceBusSku != saved.ServiceBusSku
            || this.EventHubSku != saved.EventHubSku
            || this.AzureAppId != saved.AzureAppId
            || this.KeyVaultDnsName != saved.KeyVaultDnsName
            || this.KeyVaultSecretName != saved.KeyVaultSecretName;
    }

    public void initValue()
    {
        super();

        this.AllCompanies = NoYes::Yes;
    }

    public void update()
    {
        super();

        // All companies replaces the list of selected companies.
        if (this.AllCompanies)
        {
            BDRSetupCompany::deleteFor(this);
        }
    }

/// <summary>
/// The companies the business events of this endpoint are activated in.
/// </summary>
/// <returns>A set of company IDs.</returns>
public Set companies()
{
    return BDRSetupCompany::companies(this);
}

/// <summary>
/// The selected companies; empty when the endpoint is for all companies.
/// </summary>
public display Description companyScope()
{
    return BDRSetupCompany::scope(this);
}

/// <summary>
/// Business events are activated per company, so companies can always be chosen.
/// </summary>
/// <returns>True.</returns>
public boolean canChooseCompanies()
{
    return true;
}
